/bin/bash -c "python3 - <<'PY'
import cv2, numpy as np
im=cv2.imread('first_frame.png')
# inspect Hough on crop only with different pre-processing
g=cv2.cvtColor(im,cv2.COLOR_BGR2GRAY)
crop=g[86:112,118:184]
for scale in [4,6,8]:
 up=cv2.resize(crop,None,fx=scale,fy=scale,interpolation=cv2.INTER_CUBIC)
 for p1 in [30,50,80]:
  for p2 in [10,12,15,18]:
   c=cv2.HoughCircles(up,cv2.HOUGH_GRADIENT,dp=1,minDist=5*scale,param1=p1,param2=p2,minRadius=3*scale,maxRadius=10*scale)
   if c is not None and len(c[0]):
    vals=np.round(c[0]/scale,1); vals[:,0]+=118; vals[:,1]+=86
    if len(vals)>=4: print(scale,p1,p2,vals.tolist())
PY"

